UPDATE media_shared_song SET verification=CASE WHEN expected_size IS NOT NULL AND (SELECT file_size FROM webdav_resource WHERE song_id=@{songId}) IS NOT NULL AND expected_size<>(SELECT file_size FROM webdav_resource WHERE song_id=@{songId}) THEN 'MISMATCH' ELSE 'PRESENT' END WHERE song_id=@{songId} AND EXISTS(SELECT 1 FROM webdav_resource r WHERE r.song_id=@{songId} AND r.last_scan_id IS NOT NULL AND r.archived_at IS NULL)
